// Writes server/assets.gen.ts: one `with { type: "file" }` import per file in dist/, so
// `bun build --compile` embeds the whole built site into the executable.
// Run after `vite build`, before compiling the server.
import { Glob } from "bun";
import { resolve } from "node:path";

const root = resolve(import.meta.dirname, "..");
const files = [...new Glob("**/*").scanSync({ cwd: resolve(root, "dist"), onlyFiles: true })].sort();
if (!files.includes("index.html")) throw new Error("dist/index.html not found. Run `bun run build` first.");

const lines = [
  "// Generated by server/embed.ts. Do not edit.",
  ...files.map((f, i) => `import f${i} from "../dist/${f}" with { type: "file" };`),
  "",
  "/** URL path → path of the embedded file (readable with Bun.file). */",
  "export const assets: Record<string, string> = {",
  ...files.map((f, i) => `  ${JSON.stringify("/" + f)}: f${i},`),
  "};",
  "",
];
await Bun.write(resolve(import.meta.dirname, "assets.gen.ts"), lines.join("\n"));
console.log(`Embedded ${files.length} files from dist/.`);
